/* ----------------------------------------------------------------
   웹폰트 (목업과 동일: Nanum Myeongjo + Noto Sans KR)
----------------------------------------------------------------- */
function useMockupFonts() {
  useEffect(() => {
    const id = "geomemo-fonts";
    if (document.getElementById(id)) return;
    const pre1 = document.createElement("link");
    pre1.rel = "preconnect";
    pre1.href = "https://fonts.googleapis.com";
    const pre2 = document.createElement("link");
    pre2.rel = "preconnect";
    pre2.href = "https://fonts.gstatic.com";
    pre2.crossOrigin = "anonymous";
    const link = document.createElement("link");
    link.id = id;
    link.rel = "stylesheet";
    link.href =
      "https://fonts.googleapis.com/css2?family=Noto+Sans+KR:wght@400;500;700&family=Nanum+Myeongjo:wght@400;700&display=swap";
    document.head.append(pre1, pre2, link);

    const st = document.createElement("style");
    st.textContent =
      "html,body{margin:0;background:#F1F1F4;-webkit-font-smoothing:antialiased;text-rendering:optimizeLegibility}" +
      "*{-webkit-tap-highlight-color:transparent}" +
      "::selection{background:#DCE6FB}" +
      "input,textarea,button{font-family:inherit}" +
      "::-webkit-scrollbar{width:10px;height:10px}" +
      "::-webkit-scrollbar-thumb{background:#DDDCE1;border-radius:5px;border:3px solid transparent;background-clip:content-box}";
    document.head.appendChild(st);
  }, []);
}

