/* 시/군/구별 정보 (수원·성남·청주·전주·창원처럼 여러 구로 나뉜 대도시는
   구를 합쳐 하나의 시 단위로 취급). 인구 수는 아직 채워지지 않았어요(230개
   가까운 시/군을 정확히 채우려면 통계청 자료 확인이 필요합니다) —
   population: null이면 화면에서 "정보 없음"으로 표시됩니다. */
const KOREA_INFO = Object.fromEntries(
  Object.keys(KOREA_MUNI_PATHS).map((name) => [
    name,
    {
      capitalSeat: KOREA_CAPITAL_SEATS.has(name),
      innovationCity: KOREA_INNOVATION_CITIES[name] || null,
      population: null,
    },
  ])
);


const KOREA_VIEWBOX = "0 0 509 716.1";

function MiniKoreaMap({ activeKey, highlightKeys = [], onSelectRegion, viewBox = KOREA_VIEWBOX, ghost = false }) {
  const highlightSet = new Set(highlightKeys || []);
  return (
    <svg viewBox={viewBox} style={{ width: "100%", height: "auto", display: "block", background: ghost ? "transparent" : "#FFFFFF", borderRadius: ghost ? 0 : 14 }}>
      {Object.entries(KOREA_MUNI_PATHS).map(([name, ds]) => {
        const isActive = name === activeKey;
        const isNoted = highlightSet.has(name);
        const province = KOREA_MUNI_PROVINCE[name];
        const regionColor = KOREA_GROUP_COLORS[KOREA_GROUPS[province]] || "#B5B4B8";
        const fill = ghost ? (isActive || isNoted ? regionColor : "none") : isActive || isNoted ? regionColor : "#FFFFFF";
        const fillOpacity = isActive ? 1 : isNoted ? (ghost ? 0.55 : 0.45) : 1;
        return (
          <g key={name} onClick={onSelectRegion ? () => onSelectRegion(name) : undefined} style={{ cursor: onSelectRegion ? "pointer" : "default" }}>
            {ds.map((d, i) => (
              <path key={i} d={d} fill={fill} fillOpacity={fillOpacity} stroke={ghost ? "#8B8A8E" : "#232320"} strokeWidth={ghost ? 0.35 : 0.3} strokeLinejoin="round" />
            ))}
            <title>{name}</title>
          </g>
        );
      })}
      {Object.entries(KOREA_PROVINCE_OUTLINES).map(([prov, ds]) => (
        <g key={prov} style={{ pointerEvents: "none" }}>
          {ds.map((d, i) => (
            <path key={i} d={d} fill="none" stroke={ghost ? "#5B5A5E" : "#2A2A28"} strokeWidth={ghost ? 0.6 : 0.7} strokeLinejoin="round" />
          ))}
        </g>
      ))}
    </svg>
  );
}


/* ----------------------------------------------------------------
   저장소 헬퍼 -> storage.js 로 분리
   (IndexedDB 우선, 실패 시 localStorage. 기존 데이터는 자동으로 옮겨진다.)
----------------------------------------------------------------- */

function uid() {
  if (typeof crypto !== "undefined" && crypto.randomUUID) return crypto.randomUUID();
  return "id-" + Math.random().toString(36).slice(2) + Date.now().toString(36);
}

function compressImage(file) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      const img = new window.Image();
      img.onload = () => {
        const maxDim = 720;
        let { width, height } = img;
        if (width > height && width > maxDim) {
          height = Math.round(height * (maxDim / width));
          width = maxDim;
        } else if (height > maxDim) {
          width = Math.round(width * (maxDim / height));
          height = maxDim;
        }
        const canvas = document.createElement("canvas");
        canvas.width = width;
        canvas.height = height;
        const ctx = canvas.getContext("2d");
        ctx.drawImage(img, 0, 0, width, height);
        resolve(canvas.toDataURL("image/jpeg", 0.62));
      };
      img.onerror = () => reject(new Error("이미지를 불러올 수 없습니다."));
      img.src = e.target.result;
    };
    reader.onerror = () => reject(new Error("파일을 읽을 수 없습니다."));
    reader.readAsDataURL(file);
  });
}

function shuffle(arr) {
  const a = [...arr];
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

function stripMd(s) {
  return String(s || "").replace(/\*\*/g, "");
}

/* ISO 3166-1 alpha-2 코드로 국기 이모지를 만든다 (예: "KR" -> 🇰🇷).
   기기/폰트에 따라 그림 대신 알파벳 두 글자로 보일 수 있음(OS 제약). */
function flagEmoji(iso) {
  if (!iso || iso.length !== 2) return "";
  const codePoints = [...iso.toUpperCase()].map((c) => 127397 + c.charCodeAt(0));
  return String.fromCodePoint(...codePoints);
}

function isDueToday(card) {
  if (!card.lastReviewed) return true;
  return new Date(card.lastReviewed).toDateString() !== new Date().toDateString();
}

/* "1. 나무\n2. 풀\n3. 꽃" 형식과 "아시아 > 아프리카 > 유럽" 형식을 모두 인식해서
   순서가 있는 항목 배열로 변환한다. */
function parseRankingPaste(text) {
  const trimmed = String(text || "").trim();
  if (!trimmed) return [];

  const lines = trimmed.split(/\r?\n/).map((l) => l.trim()).filter(Boolean);
  const bulletPattern = /^\s*(?:\d+\s*[.)\:]|[-•‣])\s*/;

  // 줄바꿈이 여러 줄이면 각 줄 앞의 번호/기호를 떼고 사용
  if (lines.length > 1) {
    return lines.map((l) => l.replace(bulletPattern, "").trim()).filter(Boolean);
  }

  // 한 줄에 화살표(>, →, ->)로 구분된 경우
  if (/(->|→|>)/.test(trimmed)) {
    return trimmed
      .split(/\s*(?:->|→|>)\s*/)
      .map((s) => s.replace(bulletPattern, "").trim())
      .filter(Boolean);
  }

  // 그 외: 번호만 떼고 한 줄 그대로
  return [trimmed.replace(bulletPattern, "").trim()].filter(Boolean);
}

/* 줄바꿈(\n)을 <br/>로 바꿔서 저장된 줄바꿈이 화면에도 그대로 보이게 한다. */
function renderLineBreaks(str, keyPrefix) {
  return str.split("\n").map((line, i) => (
    <React.Fragment key={`${keyPrefix}-${i}`}>
      {i > 0 && <br />}
      {line}
    </React.Fragment>
  ));
}

function renderRich(text) {
  if (!text) return text;
  const parts = String(text).split(/(\*\*[^*]+\*\*)/g);
  return parts.map((part, i) => {
    if (part.startsWith("**") && part.endsWith("**") && part.length > 4) {
      return <strong key={i}>{renderLineBreaks(part.slice(2, -2), `b${i}`)}</strong>;
    }
    return <React.Fragment key={i}>{renderLineBreaks(part, `t${i}`)}</React.Fragment>;
  });
}

/* 자유형 문제에 "______" 같은 빈칸 표시가 있으면 밑줄 선으로 보여준다. */
function renderQuestionWithBlank(text) {
  const parts = String(text || "").split(/(_{3,})/g);
  return parts.map((part, i) =>
    /^_{3,}$/.test(part) ? (
      <span key={i} style={{ display: "inline-block", width: "2.6em", borderBottom: "2px solid currentColor", verticalAlign: "middle", margin: "0 2px" }}>&nbsp;</span>
    ) : (
      <React.Fragment key={i}>{renderRich(part)}</React.Fragment>
    )
  );
}

/* 힌트: 정답의 첫 글자만 보여주고 나머지는 가린다. */
function maskAnswer(raw) {
  const s = stripMd(raw || "");
  return s.split("").map((ch, i) => (ch === " " ? " " : i === 0 ? ch : "○")).join("");
}

