function AppShell({ active, onNav, vp, children, fullBleed }) {
  const [collapsed, setCollapsed] = useState(false);
  const sidebar = !vp.isPhone;
  const sidebarWidth = collapsed ? SIDENAV_COLLAPSED_WIDTH : SIDENAV_WIDTH;
  return (
    <div style={{ background: C.pageBg, backgroundAttachment: "fixed", minHeight: "100vh", fontFamily: FONT_SANS, position: "relative" }}>
      <div style={{ position: "absolute", top: 0, left: 0, right: 0, height: 340, background: C.heroGlow, pointerEvents: "none" }} />
      {sidebar ? <SideNav active={active} onNav={onNav} collapsed={collapsed} onToggleCollapsed={() => setCollapsed((v) => !v)} /> : <TabBar active={active} onNav={onNav} />}
      <div
        style={{
          position: "relative",
          marginLeft: sidebar ? sidebarWidth : 0,
          padding: fullBleed ? 0 : sidebar ? "40px 40px 64px" : "28px 18px 104px",
          boxSizing: "border-box",
          minHeight: sidebar ? "100vh" : undefined,
          transition: "margin-left 160ms ease",
        }}
      >
        {fullBleed ? children : <div style={{ maxWidth: vp.isDesktop ? 1120 : vp.wide ? 880 : 640, margin: "0 auto" }}>{children}</div>}
      </div>
    </div>
  );
}

/* ----------------------------------------------------------------
   루트
----------------------------------------------------------------- */
function GeoMemoAppInner({ user, onSignOut }) {
  const [loaded, setLoaded] = useState(false);
  const [hasLegacyData, setHasLegacyData] = useState(false);
  const [folders, setFolders] = useState([]);
  const [cardsByFolder, setCardsByFolder] = useState({});
  const [screen, setScreen] = useState({ name: "subjects" });
  const [confirmState, setConfirmState] = useState(null);
  const closeConfirm = () => setConfirmState(null);
  const [mapNotesByCountry, setMapNotesByCountry] = useState({});
  const [reviewHistory, setReviewHistory] = useState({});
  useMockupFonts();
  const vp = useViewport();
  const wide = vp.wide;

  useEffect(() => {
    (async () => {
      // 브라우저가 저장 공간을 자동으로 비우지 않도록 요청 (실패해도 무시)
      requestPersistence();

      if (user) {
        hasLegacyLocalData().then(setHasLegacyData);
      }

      const rawFolders = await safeGet("folders");
      const parsedFolders = rawFolders ? JSON.parse(rawFolders) : [];
      const entries = await Promise.all(
        parsedFolders.map(async (f) => {
          const raw = await safeGet(`cards:${f.id}`);
          return [f.id, raw ? JSON.parse(raw) : []];
        })
      );
      setFolders(parsedFolders);
      setCardsByFolder(Object.fromEntries(entries));

      const rawIndex = await safeGet("mapnotes:index");
      const countryKeys = rawIndex ? JSON.parse(rawIndex) : [];
      const noteEntries = await Promise.all(
        countryKeys.map(async (key) => {
          const raw = await safeGet(`mapnotes:${key}`);
          return [key, raw ? JSON.parse(raw) : {}];
        })
      );
      setMapNotesByCountry(Object.fromEntries(noteEntries));

      const rawHistory = await safeGet("reviewHistory");
      setReviewHistory(rawHistory ? JSON.parse(rawHistory) : {});

      setLoaded(true);
    })();
  }, []);

  const persistFolders = useCallback(async (next) => {
    setFolders(next);
    await safeSet("folders", JSON.stringify(next));
  }, []);

  const persistCards = useCallback(async (folderId, next) => {
    setCardsByFolder((prev) => ({ ...prev, [folderId]: next }));
    await safeSet(`cards:${folderId}`, JSON.stringify(next));
  }, []);

  const addFolder = (subject, name, emoji) => persistFolders([...folders, { id: uid(), name, subject, emoji: emoji || "", createdAt: Date.now() }]);

  const deleteFolder = async (folderId) => {
    persistFolders(folders.filter((f) => f.id !== folderId));
    await safeDelete(`cards:${folderId}`);
    setCardsByFolder((prev) => {
      const copy = { ...prev };
      delete copy[folderId];
      return copy;
    });
  };

  const requestDeleteFolder = (folderId, folderName) => {
    setConfirmState({
      message: `"${folderName}" 폴더와 안의 카드를 모두 삭제할까요?`,
      onConfirm: () => {
        deleteFolder(folderId);
        closeConfirm();
      },
    });
  };

  const selectSubject = (subject) => setScreen({ name: "folders", subject });
  const backToSubjects = () => setScreen({ name: "subjects" });
  const openFolder = (subject, folderId) => setScreen({ name: "folder", subject, folderId });
  const backToFolders = (subject) => setScreen({ name: "folders", subject });
  const openQuizPicker = (subject) => setScreen({ name: "quizPicker", subject });
  const openStudy = (subject, folderId, onlyFavorites) => setScreen({ name: "study", subject, folderId, onlyFavorites: !!onlyFavorites });

  const startAddCard = (subject, folderId, type) => setScreen({ name: "cardForm", subject, folderId, cardType: type, cardId: null });
  const startEditCard = (subject, folderId, cardId) => {
    const card = (cardsByFolder[folderId] || []).find((c) => c.id === cardId);
    setScreen({ name: "cardForm", subject, folderId, cardType: card.type, cardId });
  };

  const saveCard = (subject, folderId, cardId, cardType, data) => {
    const existing = cardsByFolder[folderId] || [];
    let next;
    if (cardId) next = existing.map((c) => (c.id === cardId ? { ...c, ...data } : c));
    else next = [...existing, { id: uid(), type: cardType, favorite: false, lastReviewed: null, reviewCount: 0, correctCount: 0, ...data }];
    persistCards(folderId, next);
    setScreen({ name: "folder", subject, folderId });
  };

  const deleteCard = (subject, folderId, cardId) => {
    const existing = cardsByFolder[folderId] || [];
    persistCards(folderId, existing.filter((c) => c.id !== cardId));
    setScreen({ name: "folder", subject, folderId });
  };

  const requestDeleteCard = (subject, folderId, cardId) => {
    setConfirmState({
      message: "이 카드를 삭제할까요?",
      onConfirm: () => {
        deleteCard(subject, folderId, cardId);
        closeConfirm();
      },
    });
  };

  const toggleFavorite = (folderId, cardId) => {
    const existing = cardsByFolder[folderId] || [];
    persistCards(folderId, existing.map((c) => (c.id === cardId ? { ...c, favorite: !c.favorite } : c)));
  };

  const startQuiz = (subject, folderIds, rankingMode) => setScreen({ name: "quiz", subject, folderIds, rankingMode: rankingMode || "blank" });

  const startTodayReview = (subject, allFolderIds) => setScreen({ name: "quiz", subject, folderIds: allFolderIds, rankingMode: "blank", dueOnly: true });

  const openBackup = () => setScreen({ name: "backup" });
  const openStats = (subject) => setScreen({ name: "stats", subject });
  const openSearch = () => setScreen({ name: "search" });
  // mapSubject: "world" | "korea" — 어느 지도(세계지리/한국지리)를 보고 있는지.
  // 인자를 안 주면 마지막으로 본 지도를 그대로 이어서 연다.
  const [lastMapSubject, setLastMapSubject] = useState("world");
  const openMapHome = (subj) => {
    const mapSubject = subj || lastMapSubject;
    setLastMapSubject(mapSubject);
    setScreen({ name: "mapHome", mapSubject });
  };

  const persistMapIndex = async (keys) => {
    await safeSet("mapnotes:index", JSON.stringify(keys));
  };

  const openCountry = async (countryKey, subj) => {
    const mapSubject = subj || (KOREA_INFO[countryKey] ? "korea" : "world");
    setLastMapSubject(mapSubject);
    if (!mapNotesByCountry[countryKey]) {
      const raw = await safeGet(`mapnotes:${countryKey}`);
      setMapNotesByCountry((prev) => ({ ...prev, [countryKey]: raw ? JSON.parse(raw) : {} }));
    }
    setScreen({ name: "mapCountry", countryKey, mapSubject });
  };

  const addMapEntry = (countryKey, tagKey, data) => {
    setMapNotesByCountry((prev) => {
      const existing = prev[countryKey] || {};
      const list = existing[tagKey] || [];
      const nextForCountry = { ...existing, [tagKey]: [...list, { id: uid(), createdAt: Date.now(), ...data }] };
      const next = { ...prev, [countryKey]: nextForCountry };
      safeSet(`mapnotes:${countryKey}`, JSON.stringify(nextForCountry));
      if (!prev[countryKey]) persistMapIndex([...Object.keys(prev), countryKey]);
      return next;
    });
  };

  const deleteMapEntry = (countryKey, tagKey, entryId) => {
    setMapNotesByCountry((prev) => {
      const existing = prev[countryKey] || {};
      const list = (existing[tagKey] || []).filter((e) => e.id !== entryId);
      const nextForCountry = { ...existing, [tagKey]: list };
      const next = { ...prev, [countryKey]: nextForCountry };
      safeSet(`mapnotes:${countryKey}`, JSON.stringify(nextForCountry));
      return next;
    });
  };

  const restoreBackup = (payload) => {
    setConfirmState({
      message: `백업을 불러오면 현재 데이터가 모두 대체됩니다. 계속할까요? (폴더 ${payload.folders.length}개)`,
      onConfirm: () => {
        persistFolders(payload.folders);
        setCardsByFolder(payload.cardsByFolder || {});
        Object.entries(payload.cardsByFolder || {}).forEach(([fid, cards]) => {
          safeSet(`cards:${fid}`, JSON.stringify(cards));
        });
        closeConfirm();
      },
    });
  };

  const importLegacyData = async () => {
    const result = await migrateLegacyLocalDataToAccount();
    setHasLegacyData(false);
    if (result.migrated > 0) {
      window.location.reload();
    }
    return result;
  };

  const finishQuiz = useCallback((subject, folderIds, results) => {
    const now = Date.now();
    const grouped = {};
    results.forEach((r) => {
      if (!grouped[r.folderId]) grouped[r.folderId] = [];
      grouped[r.folderId].push(r);
    });
    setCardsByFolder((prevCards) => {
      const nextCardsByFolder = { ...prevCards };
      Object.keys(grouped).forEach((fid) => {
        const rs = grouped[fid];
        const existing = prevCards[fid] || [];
        const next = existing.map((c) => {
          const matches = rs.filter((x) => x.cardId === c.id);
          if (matches.length === 0) return c;
          const gainedCorrect = matches.filter((m) => m.correct).length;
          return { ...c, lastReviewed: now, reviewCount: c.reviewCount + matches.length, correctCount: c.correctCount + gainedCorrect };
        });
        nextCardsByFolder[fid] = next;
        safeSet(`cards:${fid}`, JSON.stringify(next));
      });
      return nextCardsByFolder;
    });
    setReviewHistory((prev) => {
      const todayKey = new Date(now).toISOString().slice(0, 10);
      const next = { ...prev, [todayKey]: (prev[todayKey] || 0) + results.length };
      safeSet("reviewHistory", JSON.stringify(next));
      return next;
    });
    setScreen({ name: "quizSummary", subject, folderIds, results });
  }, []);

  const quizExitTarget = (subject, folderIds) => {
    if (folderIds && folderIds.length === 1) setScreen({ name: "folder", subject, folderId: folderIds[0] });
    else setScreen({ name: "folders", subject });
  };

  if (!loaded) {
    return (
      <div style={{ background: C.bg, minHeight: 200, display: "flex", alignItems: "center", justifyContent: "center" }}>
        <span style={{ fontFamily: FONT_SANS, fontSize: 14, color: C.inkFaint }}>불러오는 중…</span>
      </div>
    );
  }

  const activeNav =
    screen.name === "mapHome" || screen.name === "mapCountry"
      ? "map"
      : screen.name === "search"
      ? "search"
      : screen.name === "stats"
      ? "stats"
      : screen.name === "backup"
      ? "backup"
      : "home";

  const goNav = (key) => {
    if (key === "home") setScreen({ name: "subjects" });
    else if (key === "map") setScreen({ name: "mapHome" });
    else if (key === "search") setScreen({ name: "search" });
    else if (key === "stats") setScreen({ name: "stats" });
    else if (key === "backup") setScreen({ name: "backup" });
  };

  const wrap = (child, opts) => (
    <AppShell active={activeNav} onNav={goNav} vp={vp} fullBleed={opts && opts.fullBleed}>
      {child}
      {confirmState && <ConfirmModal message={confirmState.message} onConfirm={confirmState.onConfirm} onCancel={closeConfirm} />}
    </AppShell>
  );

  const dueCountFor = (subjectId) => {
    let n = 0;
    folders.filter((f) => f.subject === subjectId).forEach((f) => {
      (cardsByFolder[f.id] || []).forEach((c) => {
        if (isDueToday(c)) n++;
      });
    });
    return n;
  };

  if (screen.name === "subjects") {
    const folderCounts = {};
    const dueCounts = {};
    SUBJECTS.forEach((s) => {
      folderCounts[s.id] = folders.filter((f) => f.subject === s.id).length;
      dueCounts[s.id] = dueCountFor(s.id);
    });
    return wrap(
      <SubjectsScreen
        wide={wide}
        isDesktop={vp.isDesktop}
        folderCounts={folderCounts}
        dueCounts={dueCounts}
        onSelectSubject={selectSubject}
        onOpenMap={openMapHome}
        onOpenSearch={openSearch}
        onOpenStats={() => openStats(null)}
        onOpenBackup={openBackup}
        folders={folders}
        cardsByFolder={cardsByFolder}
        reviewHistory={reviewHistory}
      />
    );
  }

  if (screen.name === "mapHome" || screen.name === "mapCountry") {
    const mapSubject = screen.mapSubject || "world";
    const isKorea = mapSubject === "korea";
    // 태그 종류(세계지리 MAP_TAGS vs 한국지리 KOREA_MAP_TAGS)에 상관없이,
    // 그 나라/시도에 뭐라도 필기가 있으면 "필기됨"으로 친다.
    const anyNoted = (obj) => Object.values(obj || {}).some((arr) => (arr || []).length > 0);
    const allNotedKeys = Object.keys(mapNotesByCountry).filter((k) => anyNoted(mapNotesByCountry[k]));
    const notedKeys = allNotedKeys.filter((k) => (isKorea ? !!KOREA_INFO[k] : !!COUNTRY_BY_EN[k] || !!WORLD_PATHS[EN_TO_SVGNAME[k] || k]));
    const switchSubject = (subj) => (screen.name === "mapHome" ? openMapHome(subj) : openMapHome(subj));

    if (vp.isTablet || vp.isDesktop) {
      const selectedCountry = screen.name === "mapCountry" ? screen.countryKey : null;
      return wrap(
        <MapWorkspace
          vp={vp}
          selectedCountry={selectedCountry}
          notes={selectedCountry ? mapNotesByCountry[selectedCountry] || {} : {}}
          notedKeys={notedKeys}
          onSelectCountry={(key) => openCountry(key, mapSubject)}
          onAddEntry={(tagKey, data) => addMapEntry(selectedCountry, tagKey, data)}
          onDeleteEntry={(tagKey, entryId) => deleteMapEntry(selectedCountry, tagKey, entryId)}
          folders={folders}
          cardsByFolder={cardsByFolder}
          mapSubject={mapSubject}
          onSwitchSubject={switchSubject}
        />,
        { fullBleed: true }
      );
    }

    if (screen.name === "mapHome") {
      return isKorea
        ? wrap(<KoreaMapScreen wide={wide} notedKeys={notedKeys} onSelectRegion={(key) => openCountry(key, "korea")} onBack={backToSubjects} mapSubject={mapSubject} onSwitchSubject={switchSubject} />)
        : wrap(<WorldMapScreen wide={wide} notedKeys={notedKeys} onSelectCountry={(key) => openCountry(key, "world")} onBack={backToSubjects} mapSubject={mapSubject} onSwitchSubject={switchSubject} />);
    }

    return isKorea
      ? wrap(
          <RegionNotesScreen
            wide={wide}
            regionKey={screen.countryKey}
            notes={mapNotesByCountry[screen.countryKey] || {}}
            notedKeys={notedKeys}
            onBack={() => openMapHome("korea")}
            onAddEntry={(tagKey, data) => addMapEntry(screen.countryKey, tagKey, data)}
            onDeleteEntry={(tagKey, entryId) => deleteMapEntry(screen.countryKey, tagKey, entryId)}
            onSelectRegion={(key) => openCountry(key, "korea")}
            folders={folders}
            cardsByFolder={cardsByFolder}
          />
        )
      : wrap(
          <CountryNotesScreen
            wide={wide}
            countryKey={screen.countryKey}
            notes={mapNotesByCountry[screen.countryKey] || {}}
            notedKeys={notedKeys}
            onBack={() => openMapHome("world")}
            onAddEntry={(tagKey, data) => addMapEntry(screen.countryKey, tagKey, data)}
            onDeleteEntry={(tagKey, entryId) => deleteMapEntry(screen.countryKey, tagKey, entryId)}
            onSelectCountry={(key) => openCountry(key, "world")}
            folders={folders}
            cardsByFolder={cardsByFolder}
          />
        );
  }

  if (screen.name === "backup") {
    return wrap(
      <BackupScreen
        folders={folders}
        cardsByFolder={cardsByFolder}
        onBack={backToSubjects}
        onImport={restoreBackup}
        user={user}
        onSignOut={onSignOut}
        hasLegacyData={hasLegacyData}
        onImportLegacy={importLegacyData}
      />
    );
  }

  if (screen.name === "search") {
    return wrap(
      <SearchScreen
        folders={folders}
        cardsByFolder={cardsByFolder}
        onBack={backToSubjects}
        onOpenCard={(subj, folderId, cardId) => startEditCard(subj, folderId, cardId)}
      />
    );
  }

  if (screen.name === "stats" && !screen.subject) {
    return wrap(<StatsScreen wide={wide} folders={folders} cardsByFolder={cardsByFolder} onBack={backToSubjects} />);
  }

  const subject = screen.subject;
  const subjectFolders = folders.filter((f) => f.subject === subject);
  const cardCounts = Object.fromEntries(subjectFolders.map((f) => [f.id, (cardsByFolder[f.id] || []).length]));

  if (screen.name === "folders") {
    return wrap(
      <FoldersScreen
        wide={wide}
        isDesktop={vp.isDesktop}
        subject={subject}
        folders={subjectFolders}
        cardsByFolder={cardsByFolder}
        dueCount={dueCountFor(subject)}
        onOpenFolder={(fid) => openFolder(subject, fid)}
        onAddFolder={(name, emoji) => addFolder(subject, name, emoji)}
        onRequestDeleteFolder={requestDeleteFolder}
        onOpenQuizPicker={() => openQuizPicker(subject)}
        onOpenStudy={(fid) => openStudy(subject, fid, false)}
        onOpenFavStudy={(fid) => openStudy(subject, fid, true)}
        onStartTodayReview={() => startTodayReview(subject, subjectFolders.map((f) => f.id))}
        onBack={backToSubjects}
        mapNotesByCountry={mapNotesByCountry}
        onOpenMap={() => openMapHome(subject)}
        onOpenMapCountry={(key) => openCountry(key, subject)}
      />
    );
  }

  if (screen.name === "quizPicker") {
    return wrap(<QuizPickerScreen folders={subjectFolders} cardCounts={cardCounts} onBack={() => backToFolders(subject)} onStart={(ids, mode) => startQuiz(subject, ids, mode)} />);
  }

  if (screen.name === "study") {
    const folder = folders.find((f) => f.id === screen.folderId);
    const allCards = cardsByFolder[screen.folderId] || [];
    const cards = screen.onlyFavorites ? allCards.filter((c) => c.favorite) : allCards;
    return wrap(
      <StudyScreen
        folderName={folder ? folder.name : ""}
        cards={cards}
        onlyFavorites={screen.onlyFavorites}
        onExit={() => backToFolders(subject)}
        onToggleFavorite={(cardId) => toggleFavorite(screen.folderId, cardId)}
      />
    );
  }

  if (screen.name === "folder" || screen.name === "cardForm") {
    const folder = folders.find((f) => f.id === screen.folderId);
    if (!folder)
      return wrap(<FoldersScreen wide={wide} subject={subject} folders={subjectFolders} cardsByFolder={cardsByFolder} dueCount={dueCountFor(subject)} onOpenFolder={(fid) => openFolder(subject, fid)} onAddFolder={(name, emoji) => addFolder(subject, name, emoji)} onRequestDeleteFolder={requestDeleteFolder} onOpenQuizPicker={() => openQuizPicker(subject)} onOpenStudy={(fid) => openStudy(subject, fid, false)} onOpenFavStudy={(fid) => openStudy(subject, fid, true)} onStartTodayReview={() => startTodayReview(subject, subjectFolders.map((f) => f.id))} onBack={backToSubjects} />);
    const cards = cardsByFolder[folder.id] || [];

    if (screen.name === "folder") {
      return wrap(
        <FolderScreen
          folder={folder}
          cards={cards}
          onBack={() => backToFolders(subject)}
          onAddCard={(type) => startAddCard(subject, folder.id, type)}
          onEditCard={(cardId) => startEditCard(subject, folder.id, cardId)}
          onRequestDeleteCard={(cardId) => requestDeleteCard(subject, folder.id, cardId)}
          onToggleFavorite={(cardId) => toggleFavorite(folder.id, cardId)}
          onStartQuiz={(mode) => startQuiz(subject, [folder.id], mode)}
          onStartStudy={() => openStudy(subject, folder.id, false)}
          onStartFavStudy={() => openStudy(subject, folder.id, true)}
        />
      );
    }

    const initial = screen.cardId ? cards.find((c) => c.id === screen.cardId) : null;
    return wrap(
      <CardFormScreen
        type={screen.cardType}
        initial={initial}
        onBack={() => setScreen({ name: "folder", subject, folderId: folder.id })}
        onSave={(data) => saveCard(subject, folder.id, screen.cardId, screen.cardType, data)}
        onRequestDelete={() => requestDeleteCard(subject, folder.id, screen.cardId)}
      />
    );
  }

  if (screen.name === "quiz") {
    const folderIds = screen.folderIds;
    let cardsWithFolder = [];
    folderIds.forEach((fid) => {
      const f = folders.find((x) => x.id === fid);
      (cardsByFolder[fid] || []).forEach((card) => {
        cardsWithFolder.push({ folderId: fid, folderName: f ? f.name : "", card });
      });
    });
    if (screen.dueOnly) cardsWithFolder = cardsWithFolder.filter((x) => x.card.favorite || isDueToday(x.card));
    const title = screen.dueOnly ? "오늘의 복습" : folderIds.length === 1 ? (folders.find((f) => f.id === folderIds[0]) || {}).name : "여러 폴더";
    return wrap(
      <QuizScreen
        title={title}
        subjectName={SUBJECTS.find((s) => s.id === subject)?.name}
        cardsWithFolder={cardsWithFolder}
        showFolderLabel={screen.dueOnly || folderIds.length > 1}
        rankingMode={screen.rankingMode}
        capCount={screen.dueOnly ? 999 : 12}
        onFinish={(results) => finishQuiz(subject, folderIds, results)}
        onExit={() => quizExitTarget(subject, folderIds)}
        onToggleFavorite={toggleFavorite}
        isDesktop={vp.isDesktop}
      />
    );
  }

  if (screen.name === "quizSummary") {
    return wrap(<QuizSummaryScreen results={screen.results} onRetry={() => setScreen({ name: "quiz", subject, folderIds: screen.folderIds, rankingMode: screen.rankingMode || "blank" })} onExit={() => quizExitTarget(subject, screen.folderIds)} />);
  }

  return null;
}

/* ----------------------------------------------------------------
   로그인 게이트 — Supabase가 설정돼 있으면 로그인해야 앱을 볼 수 있다.
   (설정이 없으면 예전처럼 브라우저 저장소만 쓰는 채로 그냥 통과시킨다)
----------------------------------------------------------------- */
function AuthLoadingScreen() {
  return (
    <div style={{ background: C.bg, minHeight: "100vh", display: "flex", alignItems: "center", justifyContent: "center" }}>
      <span style={{ fontFamily: FONT_SANS, fontSize: 14, color: C.inkFaint }}>불러오는 중…</span>
    </div>
  );
}

function SignInScreen({ onSignIn }) {
  const [pending, setPending] = useState(false);
  const [error, setError] = useState("");

  const handleClick = async () => {
    setError("");
    setPending(true);
    try {
      await onSignIn();
    } catch (e) {
      setError("로그인을 시작하지 못했어요. 잠시 후 다시 시도해 주세요.");
      setPending(false);
    }
  };

  return (
    <div style={{ background: C.heroGlow + ", " + C.pageBg, minHeight: "100vh", display: "flex", alignItems: "center", justifyContent: "center", padding: 20 }}>
      <div style={{ background: C.card, borderRadius: 28, padding: "44px 36px", maxWidth: 360, width: "100%", boxShadow: C.shadowLift, textAlign: "center", boxSizing: "border-box" }}>
        <Orb hue="blue" icon={Globe2} size={56} />
        <h1 style={{ fontFamily: FONT_SERIF, fontWeight: 500, fontSize: 24, color: C.ink, margin: "20px 0 6px" }}>지리 암기 노트</h1>
        <p style={{ fontFamily: FONT_SANS, fontSize: 13.5, color: C.inkSoft, margin: "0 0 28px", lineHeight: 1.6 }}>
          로그인하면 어느 기기에서나 같은 폴더·카드·지도 필기를 볼 수 있어요.
        </p>
        <PillButton full onClick={handleClick} style={{ padding: "13px 22px", opacity: pending ? 0.6 : 1 }}>
          {pending ? "이동하는 중…" : "Google로 로그인"}
        </PillButton>
        {error && <p style={{ fontFamily: FONT_SANS, fontSize: 12, color: C.wrong, marginTop: 12 }}>{error}</p>}
      </div>
    </div>
  );
}

export default function GeoMemoApp() {
  const [authState, setAuthState] = useState(() => (supabase ? { checked: false, user: null } : { checked: true, user: null }));

  useEffect(() => {
    if (!supabase) return;
    let cancelled = false;
    (async () => {
      await authReady;
      const { data } = await supabase.auth.getSession();
      if (!cancelled) setAuthState({ checked: true, user: data.session ? data.session.user : null });
    })();
    const unsubscribe = onAuthStateChange((session) => {
      setAuthState({ checked: true, user: session ? session.user : null });
    });
    return () => {
      cancelled = true;
      unsubscribe();
    };
  }, []);

  if (!authState.checked) return <AuthLoadingScreen />;
  if (supabase && !authState.user) return <SignInScreen onSignIn={signInWithGoogle} />;

  return <GeoMemoAppInner user={authState.user} onSignOut={signOutUser} />;
}
